/* ---- TIMER HELPERS (pendente) ---- */
function calcElapsed(start,end){
  const ms=(end?new Date(end):new Date())-new Date(start);
  if(ms<0)return '0s';
  const s=Math.floor(ms/1000);
  const h=Math.floor(s/3600);const m=Math.floor((s%3600)/60);const sc=s%60;
  return (h?h+'h ':'')+(m||h?m+'min ':'')+(sc+'s');
}
function iniciarTimerCRM(){
  if(G.mk._timerInterval)clearInterval(G.mk._timerInterval);
  G.mk._timerInterval=setInterval(()=>{
    if(G.modulo!=='marketing'){clearInterval(G.mk._timerInterval);G.mk._timerInterval=null;return;}
    document.querySelectorAll('.live-timer').forEach(el=>{
      const start=el.dataset.start;
      if(start) el.textContent=(el.dataset.prefix||'')+calcElapsed(start,null);
    });
  },1000);
}
function pararTimerCRM(){
  if(G.mk._timerInterval){clearInterval(G.mk._timerInterval);G.mk._timerInterval=null;}
}
/* ---- AUTO-REFRESH CRM (pega lead novo/movido por outra tela sem precisar recarregar) ---- */
function algumaJanelaAberta(){
  return !!document.querySelector('.ov:not(.hidden), .detail-ov:not(.hidden)');
}
// Lead que a I.A. (Eva) ja tentou contatar as 4 vezes (followUpStep>=4,
// numero espelha o FOLLOWUP_STEPS do eloa-bot) e o cliente nunca respondeu -
// em vez de ficar parado pra sempre em "I.A." (decisao que ficou em aberto
// numa reuniao com Aline/Rafael, 07/08/2026, e nunca foi implementada ate
// 07/09/2026), move sozinho pra "Resgate" com a tag "Nunca respondeu". Da
// mais 24h (mesmo tamanho do ultimo intervalo da Eva) depois da ultima
// mensagem antes de desistir de vez, pra dar uma ultima chance de resposta.
// So roda com o CRM aberto (Marketing ou tela IA) - nao depende do bot da
// Eva estar rodando, nem precisa mexer no eloa-bot.
async function resgatarLeadsIaSemRespostaMk(leads){
  if(G.mk.modoDemo||!fbOk())return false;
  const agora=Date.now();
  const alvos=(leads||[]).filter(l=>{
    if(l.st!=='ia'||(l.followUpStep||0)<4)return false;
    const conversa=l.conversaEloa||[];
    if(!conversa.length||conversa[conversa.length-1].role!=='model')return false;
    const ultima=l.ultimaMensagemEm||l.eloaEnviadoEm;
    if(!ultima||ultima==='NUMERO_INVALIDO')return false;
    return(agora-new Date(ultima).getTime())/3600000>=24;
  });
  for(const lead of alvos){
    const motivo='Cliente não respondeu a nenhuma das 4 tentativas automáticas da I.A. (Eva) — movido automaticamente 24h após a última mensagem sem resposta.';
    lead.st='resgate';lead.resgatado=true;lead.nuncaRespondeu=true;lead.resgateMotivo=motivo;
    await salvarCamposMk(lead.id,{st:'resgate',resgatado:true,nuncaRespondeu:true,resgateMotivo:motivo});
    await regHistMk(lead,'🔄 Movido automaticamente para Resgate',motivo,'Sistema (automático)','purple');
  }
  return alvos.length>0;
}
// O auto-refresh (a cada 10s) reconstroi o HTML de #cnt do zero - sem isso,
// a tela voltava pro topo sozinha toda vez que rodava, mesmo com a pessoa
// no meio da rolagem lendo alguma coisa mais embaixo (pedido da Aline,
// 09/09/2026). Guarda a posicao da rolagem antes e devolve depois.
function renderPreservandoScroll(fn){
  const cnt=document.getElementById('cnt');
  const scrollTop=cnt?cnt.scrollTop:0;
  // Guarda tambem a rolagem da janela inteira - em alguns painéis (ex:
  // Hoje) quem rola é a pagina, nao o #cnt por dentro.
  const scrollX=window.scrollX,scrollY=window.scrollY;
  fn();
  // Restaura em 2 camadas de requestAnimationFrame - restaurar na hora (logo
  // depois do fn()) as vezes acontecia ANTES do navegador recalcular a
  // altura da pagina nova, e a rolagem voltava a se mexer sozinha de novo
  // (achado com a Aline, 09/09/2026, mesmo depois da 1a correcao).
  const restaurar=()=>{
    window.scrollTo(scrollX,scrollY);
    const cntNovo=document.getElementById('cnt');
    if(cntNovo)cntNovo.scrollTop=scrollTop;
  };
  restaurar();
  requestAnimationFrame(()=>requestAnimationFrame(restaurar));
}
let _mkLeadsUnsub=null;
function iniciarAutoRefreshMk(){
  pararAutoRefreshMk();
  if(!fbOk()||G.mk.modoDemo)return;
  // Trocado de polling (setInterval de 60s relendo a colecao "leads"
  // inteira toda vez, mesmo sem nada ter mudado) pra listener em tempo
  // real do Firestore (onSnapshot) - so cobra leitura de novo quando um
  // documento muda de verdade, em vez de reler tudo a cada minuto pra
  // cada aba aberta. Pedido do Claude do sistema principal via Marcela,
  // 18/09/2026, apos auditoria de custo do Firebase (10x de R$150 pra
  // R$1.200/mes, quase todo em Cloud Firestore). CORRECAO (25/09/2026):
  // esse listener continua cobrando 1 leitura por documento alterado
  // enquanto a aba ficar aberta escutando, mesmo sem renderizar nada -
  // "parado de mostrar" nao e' "parado de escutar". Pausa/retomada real
  // por inatividade esta logo abaixo de pararTimerIA().
  _mkLeadsUnsub=db.collection('leads').onSnapshot(snap=>{
    if(G.modulo!=='marketing'){pararAutoRefreshMk();return;}
    if(algumaJanelaAberta())return;
    G.mk.leads=snap.docs.map(d=>({...d.data(),_docName:d.ref.path}));
    G.mk.leads.forEach(normalizarOrigemLead);
    resgatarLeadsIaSemRespostaMk(G.mk.leads).catch(e=>console.error(e));
    renderPreservandoScroll(renderMarketing);
  },e=>console.error('Erro no listener de leads (Marketing):',e));
}
function pararAutoRefreshMk(){
  if(_mkLeadsUnsub){_mkLeadsUnsub();_mkLeadsUnsub=null;}
}

function renderMarketing(){
  if(G.modulo!=='marketing')return;
  const tb=document.getElementById('tb');
  const view=G.mk.view;
  const buscaFocada=document.activeElement&&document.activeElement.id==='mk-busca';
  const buscaSelStart=buscaFocada?document.activeElement.selectionStart:null;
  const buscaSelEnd=buscaFocada?document.activeElement.selectionEnd:null;
  // Reconstruir a tela (barra de ferramentas OU o conteudo - ex: o campo de
  // data dentro de um card de Agendamento) enquanto a pessoa esta no meio
  // de digitar uma data (dia/mes/ano em campo type="date") derruba o campo
  // e joga o foco pro <body> antes do ano ser digitado - o "onchange"
  // desses campos dispara antes da data estar completa. Sem isso, era
  // impossivel terminar de digitar o ano (achado a pedido da Aline,
  // 28/08/2026). Solucao: enquanto o foco estiver em QUALQUER campo de
  // data, pula a reconstrucao inteira dessa chamada (o valor digitado ja
  // foi salvo no estado/Firestore pelo onchange; a tela so vai refletir
  // isso no proximo render de verdade, ex: proximo auto-refresh).
  // EXCECAO: os campos de periodo do Relatorio (mk-data-inicio/fim) ficam
  // de fora dessa trava - eles nao tem o problema de onchange prematuro (o
  // usuario so troca a data pelo seletor/calendario, nao digitando), e
  // bloquear aqui deixava os numeros do Relatorio travados na tela antiga
  // mesmo depois de trocar a data (achado com a Aline, 13/09/2026).
  const focado=document.activeElement;
  const dataFocada=focado?.tagName==='INPUT'&&focado?.type==='date'&&focado.id!=='mk-data-inicio'&&focado.id!=='mk-data-fim';
  if(dataFocada)return;
  tb.innerHTML=`
    <div class="tb-title"><i class="ti ti-speakerphone" style="color:var(--red)"></i> CRM</div>
    <div class="tb-sep"></div>
    <div class="tb-tabs">
      <div class="tb-tab${view==='hoje'?' on':''}" onclick="__G().mk.view='hoje';renderMarketing()"><i class="ti ti-calendar-stats"></i> Hoje</div>
      <div class="tb-tab${view==='kanban'?' on':''}" onclick="__G().mk.view='kanban';renderMarketing()"><i class="ti ti-layout-kanban"></i> Funil</div>
      <div class="tb-tab${view==='lista'?' on':''}" onclick="__G().mk.view='lista';renderMarketing()"><i class="ti ti-list"></i> Lista</div>
      <div class="tb-tab${view==='rel'?' on':''}" onclick="__G().mk.view='rel';renderMarketing()"><i class="ti ti-chart-bar"></i> Relatórios</div>
      <div class="tb-tab${view==='visitas'?' on':''}" onclick="__G().mk.view='visitas';renderMarketing()"><i class="ti ti-walk"></i> Relacionamento</div>
    </div>
    <div class="tb-spacer"></div>
    <div class="tb-filters-inline">
      ${(G.user?.r==='master'||G.user?.r==='manager')?`<select class="select-sm" onchange="__G().mk.filtroCaptador=this.value;renderMarketing()" style="min-width:120px"><option value="">👤 Vendedor</option>${['Aline',...VENDEDORES_ATIVOS].map(v=>`<option${G.mk.filtroCaptador===v?' selected':''}>${v}</option>`).join('')}</select>`:`<span class="badge" style="background:var(--bluel);color:var(--blue);font-size:12px;padding:6px 12px"><i class="ti ti-user"></i> Meus leads — ${G.user?.n||''}</span>`}
      <input type="date" id="mk-data-inicio" class="select-sm" title="Data início" value="${G.mk.filtroDataInicio}" onchange="__G().mk.filtroDataInicio=this.value;renderMarketing()" style="width:130px">
      <input type="date" id="mk-data-fim" class="select-sm" title="Data fim" value="${G.mk.filtroDataFim}" onchange="__G().mk.filtroDataFim=this.value;renderMarketing()" style="width:130px">
      ${(G.mk.filtroCaptador||G.mk.filtroDataInicio||G.mk.filtroDataFim)?'<button class="btn btn-outline btn-sm" onclick="__G().mk.filtroCaptador=\'\';__G().mk.filtroDataInicio=\'\';__G().mk.filtroDataFim=\'\';renderMarketing()"><i class=\"ti ti-x\"></i></button>':''}
    </div>
    <div class="tb-search"><i class="ti ti-search"></i><input type="text" id="mk-busca" placeholder="Buscar lead..." value="${G.mk.busca}" oninput="__G().mk.busca=this.value;renderMarketing()"></div>
    <button class="btn btn-red btn-sm" onclick="abrirModalLead()"><i class="ti ti-plus"></i> Novo Lead</button>
  `;
  if(buscaFocada){
    const buscaEl=document.getElementById('mk-busca');
    buscaEl.focus();
    buscaEl.setSelectionRange(buscaSelStart,buscaSelEnd);
  }
  const cnt=document.getElementById('cnt');
  G.mk._scrollAnterior={};
  cnt.querySelectorAll('.kb-col-body').forEach(b=>{G.mk._scrollAnterior[b.dataset.col]=b.scrollTop;});
  // Rolagem horizontal do quadro (pra ver colunas mais a direita, tipo
  // "Venda") tambem precisa ser preservada - sem isso, o auto-refresh de
  // 10 em 10s reconstroi o quadro do zero e joga a visao de volta pro
  // inicio a cada ciclo, mesmo sem a pessoa ter mexido em nada (achado a
  // pedido da Aline, 02/09/2026: rolagem so pode mudar por acao manual).
  const kanbanWrapAntigo=cnt.querySelector('.kanban-wrap');
  G.mk._scrollLeftAnterior=kanbanWrapAntigo?kanbanWrapAntigo.scrollLeft:(G.mk._scrollLeftAnterior||0);
  cnt.innerHTML='';cnt.style.cssText='flex:1;overflow:hidden;display:flex;flex-direction:column';
  if(view==='hoje') renderDashboardHoje(cnt);
  else if(view==='kanban') renderKanbanMk(cnt);
  else if(view==='lista') renderListaMk(cnt);
  else if(view==='visitas') renderVisitasDashboard(cnt,'','');
  else renderRelatoriosMk(cnt);
}

function isSeller(){return G.user?.r==='seller';}
function escondeColunaIA(){return G.user?.r==='seller'||G.user?.r==='coordenadora'||G.user?.r==='rtcred';}
/* 24/08/2026: "Visita" saiu de uso (a pedido da Aline) - fica oculta pra
   todo mundo, mas os leads que ja estavam nessa etapa continuam com os
   dados intactos, so nao aparecem mais no quadro. "Resgate" continua em
   uso, mas so pra quem nao e vendedor (coordenadora/gestao cuidam disso). */
function colunaOculta(colId){
  if(colId==='visita')return true;
  // Resgate fica escondido do vendedor normalmente, mas o Victor e' excecao
  // (a pedido da Aline, 01/09/2026): o trabalho dele e' justamente resgatar
  // lead perdido, entao ele precisa ver e mover leads pra essa coluna.
  if(colId==='resgate')return isSeller()&&G.user?.n!=='Victor';
  return false;
}
function isManager(){return G.user?.r==='manager'||G.user?.r==='master'||G.user?.r==='coordenadora'||G.user?.r==='dev';}
function isMaster(){return G.user?.r==='master';}
// Dashboard Geral fica restrito so a esses 3 logins (pedido da Aline,
// 13/09/2026) - inclusive outros masters (ex: Tiago) nao veem mais esse
// modulo, diferente do resto do sistema que segue por perfil (role).
const EMAILS_DASHBOARD_GERAL=['contato@rtcar.com.br','marcela@rtcar.com.br','rafael@rtcar.com.br'];
// Modulo IA (Eloa) e' usado so pela Aline hoje, mas antes liberava pra
// qualquer master/coordenadora - achado pela Marcela numa auditoria de
// custo do Firebase (14/09/2026): mais gente com acesso = mais telas
// abertas com o timer de 10s rodando sem necessidade.
const EMAILS_IA=['contato@rtcar.com.br'];
function podeVerModulo(mod){
  if(mod==='geral')return EMAILS_DASHBOARD_GERAL.includes((G.user?.e||'').toLowerCase());
  if(mod==='ia')return EMAILS_IA.includes((G.user?.e||'').toLowerCase());
  const r=G.user?.r||'seller';
  if(r==='master')return true;
  if(r==='coordenadora')return true;
  // seller: apenas CRM
  return mod==='marketing';
}
function mkLeadsFiltrados(){
  let ls=[...G.mk.leads];
  // CONTROLE DE ACESSO: vendedor vê só seus leads (inclui os "replicados"
  // pra ele - lead que continua do dono original mas tambem conta/aparece
  // pra um segundo vendedor, pedido da Aline 08/09/2026).
  if(isSeller())ls=ls.filter(l=>l.captador===G.user.n||l.by===G.user.n||l.captadorReplicado===G.user.n);
  // CONTROLE DE ACESSO: coordenadora ve so os leads de Compra
  if(G.user?.r==='coordenadora')ls=ls.filter(l=>l.captador===G.user.n||l.by===G.user.n||l.captadorReplicado===G.user.n);
  // CONTROLE DE ACESSO: RT Cred (resgate BV) ve so os leads que ela mesma
  // cadastrou - mesmo mecanismo da coordenadora, agora pro canal BV
  // (pedido da Aline, 08/09/2026).
  if(G.user?.r==='rtcred')ls=ls.filter(l=>l.captador===G.user.n||l.by===G.user.n||l.captadorReplicado===G.user.n);
  if(G.mk.busca){
    const b=G.mk.busca.toLowerCase();
    const bDigits=G.mk.busca.replace(/\D/g,'');
    ls=ls.filter(l=>(l.clienteNome||'').toLowerCase().includes(b)||(l.veiculo||'').toLowerCase().includes(b)||(l.id||'').toLowerCase().includes(b)||(bDigits.length>0&&(l.clienteTel||'').replace(/\D/g,'').includes(bDigits)));
  }
  if(G.mk.filtro==='abertos')ls=ls.filter(l=>!['vendido','perdido'].includes(l.st));
  if(G.mk.filtro==='vendidos')ls=ls.filter(l=>l.st==='vendido');
  if(G.mk.filtro==='perdidos')ls=ls.filter(l=>l.st==='perdido');
  if(G.mk.filtroOrigem)ls=ls.filter(l=>l.origem===G.mk.filtroOrigem);
  // filtro de captador só disponível para master/manager
  if(isManager()&&G.mk.filtroCaptador)ls=ls.filter(l=>l.captador===G.mk.filtroCaptador||l.by===G.mk.filtroCaptador);
  if(G.mk.filtroDataInicio){const di=new Date(G.mk.filtroDataInicio+'T00:00:00');ls=ls.filter(l=>{if(!l.dtISO)return true;return new Date(l.dtISO+'T00:00:00')>=di;});}
  if(G.mk.filtroDataFim){const df=new Date(G.mk.filtroDataFim+'T23:59:59');ls=ls.filter(l=>{if(!l.dtISO)return true;return new Date(l.dtISO+'T00:00:00')<=df;});}
  ls.sort((a,b)=>ordemDiaMes(a.dtISO)-ordemDiaMes(b.dtISO));
  return ls;
}

