async function confirmarPublicarTodosLitoralCar(){
  const linhas=[...document.querySelectorAll('#lcb-body tr[data-placa]')];
  if(!linhas.length)return;
  const veiculos=linhas.map(tr=>{
    const placa=tr.dataset.placa;
    const v=(G.pf.veiculos||[]).find(x=>x.placa===placa);
    return{...v,
      categoria:tr.querySelector('[data-campo="categoria"]').value,
      marca:tr.querySelector('[data-campo="marca"]').value,
      modelo:tr.querySelector('[data-campo="modelo"]').value,
      versao:tr.querySelector('[data-campo="versao"]').value.trim(),
      combustivel:tr.querySelector('[data-campo="combustivel"]').value,
    };
  });
  const semCombustivel=veiculos.filter(v=>!v.combustivel);
  if(semCombustivel.length){toast(`Selecione o combustível de todos os veículos (faltou em ${semCombustivel.length}).`,'red');return;}
  const btn=document.getElementById('btn-lcb-confirmar');
  btn.disabled=true;btn.innerHTML='<span class="spin"></span> Publicando...';
  try{
    const{resultados}=await litoralCarFetch('litoralcarPublicarEstoque',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({veiculos})});
    const ok=resultados.filter(r=>r.ok).length;
    const falhas=resultados.filter(r=>!r.ok);
    toast(`${ok}/${resultados.length} publicado(s) na LitoralCar${falhas.length?'. Veja os erros abaixo.':'!'}`,falhas.length?'red':'green',6000);
    document.getElementById('lcb-body').insertAdjacentHTML('afterbegin',`<div style="margin-bottom:10px">${resultados.map(r=>`<div style="font-size:11px;padding:4px 0;color:${r.ok?'var(--green)':'var(--red)'}">${r.ok?'✅':'❌'} ${r.placa} — ${r.ok?(r.status||'ok'):mensagemErroLitoral(r)}</div>`).join('')}</div>`);
    const mapSnap=await db.collection('litoralcar_veiculos').get();
    G.pf.litoralcarMap={};
    mapSnap.docs.forEach(d=>G.pf.litoralcarMap[d.id]=d.data());
    renderPlataformasAnuncio();
  }catch(e){
    console.error(e);
    toast('Erro ao publicar: '+e.message,'red',5000);
  }
  btn.disabled=false;btn.innerHTML='<i class="ti ti-upload"></i> Publicar todos';
}
window.abrirPublicarTodosLitoralCar=abrirPublicarTodosLitoralCar;
window.confirmarPublicarTodosLitoralCar=confirmarPublicarTodosLitoralCar;

let _pfPublicarCtx=null;
async function abrirPublicarPlataforma(placa,plataformaId){
  const v=(G.pf.veiculos||[]).find(x=>x.placa===placa);
  if(!v)return;
  _pfPublicarCtx={placa,plataformaId};
  const plataforma=PLATAFORMAS_ANUNCIO.find(p=>p.id===plataformaId);
  document.getElementById('pp-titulo').textContent=`Publicar na ${plataforma?.nome||plataformaId}`;
  const body=document.getElementById('pp-body');
  body.innerHTML='Carregando referências...';
  document.getElementById('ov-plataforma-publicar').classList.remove('hidden');
  try{
    if(!G.pf.litoralcarRefs)G.pf.litoralcarRefs=await litoralCarFetch('litoralcarReferencias');
    const{categorias=[],combustiveis=[]}=G.pf.litoralcarRefs;
    const categoriaSugerida=litoralCarCategoriaSugerida(v.marca);
    const mm=await litoralCarMarcasModelos(categoriaSugerida);
    const marcaSugerida=melhorCorrespondenciaLitoral(v.marca,mm.marcas);
    const modelosDaMarca=mm.modelos.filter(m=>m.marca===marcaSugerida).map(m=>m.modelo);
    const modeloSugerido=melhorCorrespondenciaLitoral(v.modelo,modelosDaMarca);
    body.innerHTML=`
      <p style="font-size:12px;color:var(--tx2);margin-bottom:10px">Nosso cadastro: <strong>${[v.marca,v.modelo,v.versao].filter(Boolean).join(' ')}</strong> — ${v.placa}. Confira/corrija marca, modelo e versão como devem aparecer na LitoralCar.</p>
      <div class="field"><label>Categoria</label><select id="pp-categoria" style="width:100%" onchange="ppAtualizarMarcas()">${categorias.map(c=>`<option ${c===categoriaSugerida?'selected':''}>${c}</option>`).join('')}</select></div>
      <div class="field"><label>Marca</label><select id="pp-marca" style="width:100%" onchange="ppAtualizarModelos()"></select></div>
      <div class="field"><label>Modelo</label><select id="pp-modelo" style="width:100%"></select></div>
      <div class="field"><label>Versão</label><input type="text" id="pp-versao" value="${(v.versao||'').trim()}" style="width:100%"></div>
      <div class="field"><label>Combustível</label><select id="pp-combustivel" style="width:100%"><option value="">selecione...</option>${combustiveis.map(c=>`<option ${c==='Flex'?'selected':''}>${c}</option>`).join('')}</select></div>
      ${v.preco?'':'<p style="color:var(--red);font-size:12px;margin-top:8px">⚠️ Este veículo está sem preço no estoque — a LitoralCar vai recusar.</p>'}`;
    _ppMarcasModelos=mm;
    popularSelectLitoral('pp-marca',mm.marcas,marcaSugerida);
    popularSelectLitoral('pp-modelo',modelosDaMarca,modeloSugerido);
  }catch(e){
    body.innerHTML=`<p style="color:var(--red)">Erro: ${e.message}</p>`;
  }
}
