/* Sugestao de cliente ja cadastrado no sistema principal (cadastroPF/PJ da
   Marcela) ao criar um lead - pedido da Aline, 17/09/2026: "ao informar um
   lead e ele ja ser da nossa base de dados, o sistema buscar as
   informacoes". Busca por nome OU telefone (qualquer um dos dois campos
   digitado), com debounce pra nao disparar uma function a cada tecla.
   So LEITURA - nunca grava nada de volta no cadastro dela. */
let _leadClienteBuscaTimer=null;
function leadClienteSugerir(){
  clearTimeout(_leadClienteBuscaTimer);
  const nome=document.getElementById('f-nome').value.trim();
  const tel=document.getElementById('f-tel').value.trim();
  const q=tel.replace(/\D/g,'').length>=6?tel:nome;
  if(nome.length<3&&tel.replace(/\D/g,'').length<6){
    document.getElementById('lead-cliente-sug').style.display='none';
    return;
  }
  _leadClienteBuscaTimer=setTimeout(()=>leadClienteBuscar(q),400);
}
async function leadClienteBuscar(q){
  const box=document.getElementById('lead-cliente-sug');
  try{
    const{resultados}=await litoralCarFetch(`buscarClienteCadastro?q=${encodeURIComponent(q)}`);
    if(!resultados||!resultados.length){box.style.display='none';box.innerHTML='';return;}
    box.innerHTML=resultados.map(r=>`<div data-id="${r.id}" onmousedown="leadClienteEscolher('${r.id}')" style="padding:8px 12px;cursor:pointer;border-bottom:1px solid var(--bdr);display:flex;justify-content:space-between;gap:8px;align-items:center" onmouseover="this.style.background='var(--bg3)'" onmouseout="this.style.background=''"><span style="font-size:12px;font-weight:600">${r.tipo==='PF'?'👤':'🏢'} ${r.nome}</span><span style="font-size:11px;color:var(--tx3);white-space:nowrap">${r.tel||''}</span></div>`).join('');
    box.dataset.resultados=JSON.stringify(resultados);
    box.style.display='block';
  }catch(e){
    console.error('Erro ao buscar cliente no cadastro:',e);
    box.style.display='none';
  }
}
function leadClienteEscolher(id){
  const box=document.getElementById('lead-cliente-sug');
  const resultados=JSON.parse(box.dataset.resultados||'[]');
  const c=resultados.find(r=>r.id===id);
  box.style.display='none';
  if(!c)return;
  document.getElementById('f-nome').value=c.nome||'';
  if(c.tel){const elTel=document.getElementById('f-tel');elTel.value=c.tel;mascaraTel(elTel);}
  if(c.email)document.getElementById('f-email').value=c.email;
  document.getElementById('f-cliente-cidade').value=c.cidade||'';
  document.getElementById('f-cliente-uf').value=c.uf||'';
  toast(`Dados preenchidos: ${c.nome}`);
}
window.leadClienteSugerir=leadClienteSugerir;
window.leadClienteEscolher=leadClienteEscolher;

async function salvarLead(){
  const nome=document.getElementById('f-nome').value.trim(),tel=document.getElementById('f-tel').value.trim(),origem=document.getElementById('f-origem').value;
  if(!nome){toast('Informe o nome','red');return;}if(!tel){toast('Informe o telefone','red');return;}if(!origem){toast('Selecione a origem','red');return;}
  // "Compra" e "BV" sao canais de proposito diferente (troca/resgate) - o
  // MESMO cliente pode legitimamente ter mais de um lead aberto ao mesmo
  // tempo, um de cada tipo (ex: Luciano vendeu um carro com o Maicon E
  // vendeu outro que virou Compra da Milena). Por isso esses dois nao
  // caem no aviso de "lead duplicado" (pedido da Aline, 09/09/2026 -
  // mesma regra ja combinada antes pra Gui/BV).
  const origemPermiteDuplicado=origem==='Compra'||origem==='BV';
  if(!G.mk.editandoId&&!origemPermiteDuplicado){
    const telDigits=tel.replace(/\D/g,'');
    const dup=G.mk.leads.find(l=>l.clienteTel&&l.clienteTel.replace(/\D/g,'')===telDigits&&!['vendido','perdido'].includes(l.st));
    if(dup){
      const colDup=COLS_MK.find(c=>c.id===dup.st);
      document.getElementById('lead-duplicado-msg').innerHTML=`Já existe um lead em aberto com esse telefone: <strong>${dup.id} — ${dup.clienteNome||'(sem nome)'}</strong>, na etapa <strong>${colDup?.label||dup.st}</strong>${dup.captador?` com <strong>${dup.captador}</strong>`:''}.<br><br>Avise o Master pra confirmar quem deve continuar esse atendimento, em vez de cadastrar de novo.`;
      document.getElementById('ov-lead-duplicado').classList.remove('hidden');
      setTimeout(()=>document.getElementById('btn-duplicado-entendi').focus(),50);
      return;
    }
  }
  const btn=document.getElementById('btn-salvar-lead');btn.disabled=true;document.getElementById('btn-salvar-lead-txt').innerHTML='<span class="spin"></span>';
  let captador=document.getElementById('f-captador').value;if(origem==='Compra'&&!captador)captador='Milena';
  if(!captador&&!G.mk.editandoId)captador=await proximoVendedorRodizio();
  // TRAVA: Aline e' Master, nunca vendedora - nao pode salvar lead nenhum
  // com ela como captador (achado 09/09/2026, ver comentario em
  // VENDEDORES_ATIVOS). Cai pro rodizio se for lead novo, ou pede pra
  // escolher se for edicao.
  if(captador==='Aline'){
    if(!G.mk.editandoId){captador=origem==='Compra'?'Milena':await proximoVendedorRodizio();}
    else{btn.disabled=false;document.getElementById('btn-salvar-lead-txt').textContent='Salvar Alterações';toast('Aline não pode ser vendedor(a) de um lead — escolha outra pessoa em "Vendedor".','red',4000);return;}
  }
  const dtISO=document.getElementById('f-data-contato').value||new Date().toISOString().split('T')[0];
  const stEscolhido=document.getElementById('f-etapa').value||'aguardando';
  const agora=new Date().toISOString();
  const leadExistente=G.mk.editandoId?G.mk.leads.find(l=>l.id===G.mk.editandoId):null;
  const data={clienteNome:nome,clienteTel:tel,clienteEmail:document.getElementById('f-email').value.trim(),clienteCidade:document.getElementById('f-cliente-cidade').value.trim(),clienteUF:document.getElementById('f-cliente-uf').value.trim(),origem,captador:captador||G.user?.n||'',by:G.user?.n||'',uid:G.user?.id||'',veiculo:document.getElementById('f-veiculo').value.trim(),veiculoPlaca:document.getElementById('f-veiculo-placa').value.trim(),veiculoTroca:_veiculoTrocaAtual||null,valor:document.getElementById('f-valor').value.trim(),st:stEscolhido,dtISO,dt:isoParaBR(dtISO),obs:document.getElementById('f-obs').value.trim()};
  // Cronometro das colunas com timer (Atendimento/Agendamento): sem isso, um
  // lead criado ou movido manualmente pra essas etapas nunca teria a contagem
  // em vermelho, so os que chegavam automaticamente pelo Autoconf/Eva.
  if(stEscolhido==='atendimento'&&!(leadExistente&&leadExistente.atendimento_at))data.atendimento_at=agora;
  if(stEscolhido==='agendamento'&&!(leadExistente&&leadExistente.pendente_at))data.pendente_at=agora;
  if(stEscolhido==='encantamento'&&!(leadExistente&&leadExistente.encantamento_at))data.encantamento_at=agora;
  if(stEscolhido==='negociacao'&&!(leadExistente&&leadExistente.negociacao_at))data.negociacao_at=agora;
  // Sem isso, marcar "Venda" direto pelo dropdown de Etapa (em vez do botao
  // "✅ Vendido") nunca gravava a data da venda - achado ao investigar por
  // que o painel "Hoje" nao batia com vendas que a Aline sabia que tinham
  // acontecido (27/08/2026).
  if(stEscolhido==='vendido'&&!(leadExistente&&leadExistente.dtVenda))data.dtVenda=hoje();
  try{
    if(G.mk.editandoId){Object.assign(G.mk.leads.find(l=>l.id===G.mk.editandoId),data);await salvarCamposMk(G.mk.editandoId,data);toast('Lead atualizado!');}
    else{const id=await proximoId('LEAD',G.mk.leads,'leads_config/mk','leadSeq');const lead={id,convertido:false,dtVenda:'',motivoPerda:'',historico:[],_criadoEm:agora,...data};G.mk.leads.push(lead);if(!G.mk.modoDemo)await fbCreate('leads',id,lead);await regHistMk(lead,'Lead criado',`Origem: ${data.origem}`,G.user?.n||data.captador||'');toast(`Lead ${id} criado!`);}
    fecharModal('ov-lead');renderMarketing();
  }catch(e){console.error(e);toast('Erro ao salvar','red');}
  finally{btn.disabled=false;document.getElementById('btn-salvar-lead-txt').textContent=G.mk.editandoId?'Salvar Alterações':'Salvar Lead';}
}
// Aline e' Master (gestao/dona), nunca vendedora - nao compra nem vende
// carro, entao nao pode aparecer como captador de lead nenhum (achado
// 09/09/2026: Milena registrou uma Compra sem querer logada como Aline,
// e o mes contou errado). Tirada da lista de quem pode ser escolhido como
// vendedor/captador (dropdown, Transferir, Replicar) - ver tambem a trava
// em salvarLead().
const VENDEDORES_ATIVOS=['Marcela','Rafael','Milena','Janderson','Maicon','Rubens','Jean','Victor','Guilmara'];
// Popup de "Transferir/Replicar/Vendedor" abre pra baixo por padrao - no
// ultimo card de cada coluna (perto do fim da tela) isso cortava a lista,
// escondendo os ultimos nomes. Agora mede se cabe embaixo e, se nao couber,
// abre pra cima (pedido da Aline, 11/09/2026).
function posicionarPopupPertoDoBotao(popup,btn){
  const rect=btn.getBoundingClientRect();
  popup.style.left=rect.left+'px';
  const alturaPopup=popup.offsetHeight;
  const espacoAbaixo=window.innerHeight-rect.bottom;
  if(espacoAbaixo<alturaPopup+10&&rect.top>alturaPopup+10){
    popup.style.top=(rect.top-alturaPopup-6)+'px';
  }else{
    popup.style.top=(rect.bottom+6)+'px';
  }
}
let _transferPopup=null;
function abrirTransferirLead(id,e){
  e.stopPropagation();
  if(_transferPopup){_transferPopup.remove();_transferPopup=null;}
  const popup=document.createElement('div');
  popup.className='transfer-popup';
  popup.innerHTML=`<div class="tp-title">Transferir para</div>${VENDEDORES_ATIVOS.map(v=>`<button onclick="confirmarTransferencia('${id}','${v}')">${v}</button>`).join('')}`;
  document.getElementById('rtcar-crm-root').appendChild(popup);
  const btn=e.currentTarget;
  posicionarPopupPertoDoBotao(popup,btn);
  _transferPopup=popup;
  setTimeout(()=>document.addEventListener('click',()=>{popup.remove();_transferPopup=null;},{once:true}),50);
}
async function confirmarTransferencia(id,vendedor){
  if(_transferPopup){_transferPopup.remove();_transferPopup=null;}
  const lead=G.mk.leads.find(l=>l.id===id);
  if(!lead)return;
  lead.captador=vendedor;
  await salvarCamposMk(id,{captador:vendedor});
  renderMarketing();
  toast(`Lead transferido para ${vendedor}`);
}
/* "Replicar" - pra negocio que envolve 2 pessoas ao mesmo tempo (ex: Maicon
   vende o carro novo, Milena compra o usado do cliente na troca) - o MESMO
   lead passa a contar pros 2, sem duplicar o registro. Diferente de
   "Transferir" (que troca o dono), aqui os 2 continuam donos e os 2 ganham
   credito se a venda fechar (pedido da Aline, 08/09/2026 - caso real:
   LEAD-290, Luciano, Maicon + Milena). */
let _replicarPopup=null;
function abrirReplicarLead(id,e){
  e.stopPropagation();
  if(_replicarPopup){_replicarPopup.remove();_replicarPopup=null;}
  const lead=G.mk.leads.find(l=>l.id===id);
  const popup=document.createElement('div');
  popup.className='transfer-popup';
  popup.innerHTML=`<div class="tp-title">Replicar também para</div>${VENDEDORES_ATIVOS.filter(v=>v!==lead?.captador).map(v=>`<button onclick="confirmarReplicacao('${id}','${v}')">${v}</button>`).join('')}${lead?.captadorReplicado?`<button onclick="confirmarReplicacao('${id}','')" style="color:var(--red)">Remover réplica (${lead.captadorReplicado})</button>`:''}`;
  document.getElementById('rtcar-crm-root').appendChild(popup);
  const btn=e.currentTarget;
  posicionarPopupPertoDoBotao(popup,btn);
  _replicarPopup=popup;
  setTimeout(()=>document.addEventListener('click',()=>{popup.remove();_replicarPopup=null;},{once:true}),50);
}
async function confirmarReplicacao(id,vendedor){
  if(_replicarPopup){_replicarPopup.remove();_replicarPopup=null;}
  const lead=G.mk.leads.find(l=>l.id===id);
  if(!lead)return;
  lead.captadorReplicado=vendedor;
  await salvarCamposMk(id,{captadorReplicado:vendedor});
  await regHistMk(lead,vendedor?'🔗 Réplica de crédito':'🔗 Réplica removida',vendedor?`Esse lead também passa a contar para ${vendedor}, além de ${lead.captador||lead.by||'?'}.`:'A réplica de crédito foi removida.',G.user?.n||'','purple');
  renderMarketing();
  toast(vendedor?`Lead replicado também para ${vendedor}`:'Réplica removida');
}
