async function vincularClienteRelacionamento(lead){
  const telDigits=(lead.clienteTel||'').replace(/\D/g,'');
  if(!telDigits)return;
  try{
    let clientes=G.rel.clientes;
    if(!G.rel.modoDemo&&(!clientes||!clientes.length))clientes=await fbList('clientes_rel');
    clientes=clientes||[];
    if(clientes.some(c=>(c.clienteTel||'').replace(/\D/g,'')===telDigits))return;
    const data={clienteNome:lead.clienteNome||'',clienteTel:lead.clienteTel||'',clienteEmail:lead.clienteEmail||'',dtNascimento:'',responsavel:lead.captador||lead.by||'',by:lead.captador||lead.by||'',uid:lead.uid||'',veiculo:lead.veiculo||'',dtCompra:new Date().toISOString().split('T')[0],valor:lead.valor||'',st:'nome',obs:`Convertido automaticamente do lead ${lead.id}`};
    const id=await proximoId('REL',clientes,'rel_config/seq','relSeq');
    const cliente={id,historico:[],...data};
    if(!G.rel.modoDemo)await fbCreate('clientes_rel',id,cliente);
    if(Array.isArray(G.rel.clientes))G.rel.clientes.push(cliente);
    await regHistRel(cliente,'📋 Cliente cadastrado',`Convertido automaticamente do lead ${lead.id} ao fechar venda`,data.responsavel,'📋');
  }catch(e){console.error('Erro ao vincular cliente em Relacionamento',e);}
}
// Fecha qualquer cronometro de etapa que tenha ficado aberto (_at sem
// _end), na hora de chegar num estagio final (Vendido/Perdido) que nao
// passa pelo moverLead() - pedido da Aline, 23/09/2026: temporizador em
// todas as colunas, incluindo saber quanto tempo durou a etapa anterior.
function fecharTimersAbertosMk(lead,extras){
  ['atendimento','encantamento','negociacao','pendente','visita','resgate'].forEach(campo=>{
    const campoAt=campo+'_at',campoEnd=campo+'_end';
    if(lead[campoAt]&&!lead[campoEnd]){lead[campoEnd]=new Date().toISOString();extras[campoEnd]=lead[campoEnd];}
  });
}
async function confirmarVendido(){
  const id=G.mk.detailId,lead=G.mk.leads.find(l=>l.id===id);if(!lead)return;
  const veiculo=document.getElementById('vend-veiculo').value.trim(),placa=document.getElementById('vend-placa').value.trim(),obs=document.getElementById('vend-obs').value.trim(),repasse=document.getElementById('vend-repasse').checked;
  if(veiculo)lead.veiculo=veiculo;lead.veiculoPlaca=placa;lead.st='vendido';lead.convertido=true;lead.dtVenda=hoje();lead.repasse=repasse;
  const camposVenda={st:'vendido',convertido:true,dtVenda:hoje(),veiculo:lead.veiculo,veiculoPlaca:placa,repasse};
  if(!lead.vendido_at){lead.vendido_at=new Date().toISOString();camposVenda.vendido_at=lead.vendido_at;}
  fecharTimersAbertosMk(lead,camposVenda);
  if(lead.resgatado){lead.vendaRecuperada=true;camposVenda.vendaRecuperada=true;}
  await salvarCamposMk(id,camposVenda);
  await regHistMk(lead,lead.vendaRecuperada?'🎉 Vendido (venda recuperada)':'🎉 Vendido',(repasse?'🔁 Repasse — ':'')+(obs||'Negócio fechado!'),G.user?.n||'','green');
  await vincularClienteRelacionamento(lead);
  fecharModal('ov-vendido');toast(lead.vendaRecuperada?'🎉 Venda recuperada com sucesso!':'🎉 Venda registrada!');if(G.mk.detailId===id)abrirDetailLead(id);renderMarketing();
  // Fase 3 (16/09/2026, mesmo espirito da Fase 2/Avaliacao): ao confirmar a
  // venda, pula direto pro Termo de Venda ja preenchido com o que o CRM
  // sabe (cliente/telefone/veiculo/placa/valor) - o vendedor/Marcela
  // completa o resto (forma de pagamento, veiculo de troca formal etc)
  // pelo formulario normal deles. Embutido chama a funcao direto (mesma
  // janela); standalone abre o sistema principal em aba nova com os dados
  // na URL - os dois dependem de window.abrirTermoDoCRM existir do lado
  // dela; enquanto nao existir, isso e' um no-op no modo embutido.
  const dadosTermo={leadId:lead.id,cliente:lead.clienteNome,telefone:lead.clienteTel,origem:lead.origem,veiculo:{descricao:lead.veiculo,placa:lead.veiculoPlaca,preco:lead.valor}};
  if(window.RTCARCRM_EMBED&&typeof window.abrirTermoDoCRM==='function'){
    window.abrirTermoDoCRM(dadosTermo);
  }else if(!window.RTCARCRM_EMBED){
    const payloadTermo=btoa(unescape(encodeURIComponent(JSON.stringify(dadosTermo))));
    window.open(`${URL_SISTEMA_PRINCIPAL}?crmTermo=${encodeURIComponent(payloadTermo)}`,'_blank');
  }
}
