// Encaminhamento manual da I.A. pra Atendimento, sem depender da Eva -
// pedido da Aline, 20/09/2026, no dia em que os creditos da Anthropic
// zeraram e a Eva parou de conseguir gerar qualquer resposta (sem isso,
// o time ficava sem jeito nenhum de tirar um lead da I.A. e mandar pro
// rodizio). Faz exatamente o que o encaminharParaConsultor() da Eva faz
// do lado do bot: muda pra 'atendimento', sorteia vendedor pelo rodizio
// (se ainda nao tiver um) e grava atendimento_at - a notificacao por
// WhatsApp pro vendedor continua sendo mandada pelo proprio bot (que so
// depende da conexao com o WhatsApp, nao da IA), assim que ele rodar o
// proximo ciclo.
async function encaminharParaAtendimentoMk(id){
  const lead=G.mk.leads.find(l=>l.id===id);if(!lead)return;
  if(!confirm(`Encaminhar ${lead.clienteNome||id} direto pro rodízio de vendedor, sem esperar a Eva?`))return;
  let captador=lead.captador;
  if(!captador||captador==='Aline')captador=await proximoVendedorRodizio();
  const agora=new Date().toISOString();
  const campos={st:'atendimento',captador,atendimento_at:lead.atendimento_at||agora};
  lead.st='atendimento';lead.captador=captador;lead.atendimento_at=campos.atendimento_at;
  await salvarCamposMk(id,campos);
  await regHistMk(lead,'➡️ Encaminhado manualmente pra Atendimento',`Enviado direto pro rodízio (Eva indisponível) — vendedor: ${captador}`,G.user?.n||'','purple');
  toast(`${lead.clienteNome||id} encaminhado pra ${captador}!`);
  renderMarketing();
}
window.encaminharParaAtendimentoMk=encaminharParaAtendimentoMk;
// Versao em lote do botao acima - mesma logica, so' que pra todos os leads
// da I.A. que nunca tiveram conversa de verdade (nem eloaEnviadoEm valido,
// nem conversaEloa) de uma vez, incluindo os marcados NUMERO_INVALIDO
// (pedido da Aline, 20/09/2026: "quero ate os leads antigos, qualquer um
// que nao foi abordado" - achou 31 parados, alguns ha 300h+).
async function encaminharTodosIA(){
  const alvos=G.mk.leads.filter(l=>l.st==='ia'&&!(l.eloaEnviadoEm&&l.eloaEnviadoEm!=='NUMERO_INVALIDO')&&!(l.conversaEloa&&l.conversaEloa.length));
  if(!alvos.length){toast('Nenhum lead pendente na I.A.');return;}
  if(!confirm(`Isso vai mover ${alvos.length} lead(s) da I.A. direto pra Atendimento, sorteando um vendedor (Janderson/Maicon/Victor) pra cada um. Confirma?`))return;
  toast(`Encaminhando ${alvos.length} lead(s)...`,'gold',6000);
  let ok=0;
  for(const lead of alvos){
    try{
      let captador=lead.captador;
      if(!captador||captador==='Aline')captador=await proximoVendedorRodizio();
      const agora=new Date().toISOString();
      const campos={st:'atendimento',captador,atendimento_at:lead.atendimento_at||agora};
      lead.st='atendimento';lead.captador=captador;lead.atendimento_at=campos.atendimento_at;
      await salvarCamposMk(lead.id,campos);
      await regHistMk(lead,'➡️ Encaminhado manualmente pra Atendimento','Enviado em lote pro rodízio (Eva indisponível) — vendedor: '+captador,G.user?.n||'','purple');
      ok++;
    }catch(e){console.error(`Erro ao encaminhar ${lead.id}:`,e);}
  }
  toast(`${ok}/${alvos.length} lead(s) encaminhado(s)!`,'green',6000);
  renderMarketing();
}
