async function moverLead(id,novaCol){
  const lead=G.mk.leads.find(l=>l.id===id);if(!lead)return;
  if(lead.st==='encantamento'&&['agendamento','negociacao'].includes(novaCol)){
    const feitas=[lead.encVideoTecnico,lead.encVideoLoja,lead.encTelefone].filter(Boolean).length;
    if(feitas<2){toast('Complete pelo menos 2 das 3 etapas do Encantamento antes de avançar','red',4000);return;}
  }
  const oldLabel=COLS_MK.find(c=>c.id===lead.st)?.label;
  const extras={};
  if(novaCol==='agendamento'&&!lead.pendente_at){
    lead.pendente_at=new Date().toISOString();extras.pendente_at=lead.pendente_at;
  }
  if((novaCol==='vendido'||novaCol==='perdido')&&lead.pendente_at&&!lead.pendente_end){
    lead.pendente_end=new Date().toISOString();extras.pendente_end=lead.pendente_end;
  }
  if(novaCol==='atendimento'&&!lead.atendimento_at){
    lead.atendimento_at=new Date().toISOString();extras.atendimento_at=lead.atendimento_at;
  }
  if(novaCol!=='atendimento'&&lead.atendimento_at&&!lead.atendimento_end){
    lead.atendimento_end=new Date().toISOString();extras.atendimento_end=lead.atendimento_end;
  }
  // Mesmo padrao do Atendimento, agora tambem pro cronometro de
  // Encantamento e Negociacao (a pedido da Aline, 27/08/2026) - e depois
  // Visita e Resgate tambem (pedido da Aline, 23/09/2026: "quero o
  // temporizador em todas as colunas", pra aparecer na tela de detalhe/
  // historico independente da etapa atual do lead).
  ['encantamento','negociacao','visita','resgate'].forEach(colId=>{
    const campoAt=colId+'_at',campoEnd=colId+'_end';
    if(novaCol===colId&&!lead[campoAt]){
      lead[campoAt]=new Date().toISOString();extras[campoAt]=lead[campoAt];
    }
    if(novaCol!==colId&&lead[campoAt]&&!lead[campoEnd]){
      lead[campoEnd]=new Date().toISOString();extras[campoEnd]=lead[campoEnd];
    }
  });
  lead.st=novaCol;
  await salvarCamposMk(id,Object.assign({st:novaCol},extras));
  await regHistMk(lead,`${COLS_MK.find(c=>c.id===novaCol)?.emoji} Movido para ${COLS_MK.find(c=>c.id===novaCol)?.label}`,`Anterior: ${oldLabel}`,G.user?.n||'','blue');
  toast(`Lead → ${COLS_MK.find(c=>c.id===novaCol)?.label}`);abrirDetailLead(id);renderMarketing();
}
