async function regHistMk(lead,acao,obs,by,icone='blue'){
  if(!lead.historico)lead.historico=[];
  lead.historico.push({dt:hoje(),icone,acao,obs,by});
  const campos={historico:lead.historico};
  // O cronometro de cada coluna mostra ha quanto tempo o lead esta SEM
  // receber atencao, nao o tempo total que ele leva na etapa - toda vez
  // que uma acao e registrada (mensagem, foto, video, observacao, mudar
  // de etapa...) o relogio da etapa atual zera e recomeca a contar dali.
  // "ia" fica de fora porque _criadoEm precisa continuar sendo a data
  // real de criacao do lead, usada em outros lugares do sistema (a
  // pedido da Aline, 02/09/2026).
  const [campoStart]=CAMPOS_TIMER_COL[lead.st]||[null];
  if(campoStart&&campoStart!=='_criadoEm'){
    const agora=new Date().toISOString();
    lead[campoStart]=agora;
    campos[campoStart]=agora;
  }
  await salvarCamposMk(lead.id,campos);
}
async function salvarCamposMk(id,campos){if(G.mk.modoDemo)return;try{await fbUpdate('leads',id,campos);}catch(e){console.error(e);toast('Erro ao salvar','red');}}

function abrirDetailLead(id){
  G.mk.detailId=id;const lead=G.mk.leads.find(l=>l.id===id);if(!lead)return;
  const col=COLS_MK.find(c=>c.id===lead.st)||COLS_MK[0];
  // Mesmo cronometro que ja aparece no card do Kanban, so que faltava aqui
  // na tela de detalhe/historico (pedido da Aline, 23/09/2026).
  const[campoStartEtapa,campoEndEtapa]=CAMPOS_TIMER_COL[col.id]||[null,null];
  const timerStartEtapa=campoStartEtapa?lead[campoStartEtapa]:null;
  const timerEndEtapa=campoEndEtapa?lead[campoEndEtapa]:null;
  const timerEtapaHtml=timerStartEtapa&&!timerEndEtapa?
    `<span class="live-timer" data-start="${timerStartEtapa}" style="color:#e8431e;font-weight:700">calculando...</span>`:
    (timerStartEtapa&&timerEndEtapa?`${calcElapsed(timerStartEtapa,timerEndEtapa)}`:null);
  document.getElementById('detail-ov').classList.remove('hidden');
  const pnl=document.getElementById('detail-pnl');pnl.classList.remove('hidden');
  const hist=(lead.historico||[]).slice().reverse();
  const histHtml=hist.length?hist.map(h=>{const dotBg={blue:'var(--bluel)',green:'var(--greenl)',red:'var(--redl)',gold:'var(--goldl)',purple:'var(--purplel)'}[h.icone||'blue']||'var(--bluel)';const dotC={blue:'var(--blue)',green:'var(--green)',red:'var(--red)',gold:'var(--gold)',purple:'var(--purple)'}[h.icone||'blue']||'var(--blue)';
    return`<div class="hist-item"><div class="hist-dot" style="background:${dotBg};color:${dotC}"><i class="ti ti-${h.icone==='green'?'check':h.icone==='red'?'x':h.icone==='gold'?'phone':h.icone==='purple'?'calendar':'circle-plus'}"></i></div><div class="hist-info"><div class="hist-acao">${h.acao}</div>${h.obs?`<div class="hist-obs">${h.obs}</div>`:''}<div class="hist-meta">${h.dt} · ${h.by||'Sistema'}</div></div></div>`;
  }).join(''):'<div style="color:var(--tx3);font-size:12px">Nenhuma interação registrada.</div>';
  const SEQ_MK=['ia','atendimento','encantamento','negociacao','agendamento','visita','vendido'];
  const idxAtualMk=SEQ_MK.indexOf(lead.st);
  const movBtns=COLS_MK.filter(c=>c.id!==lead.st&&!['vendido','perdido'].includes(c.id)&&(c.id!=='resgate'||!lead.optOutContato)&&(lead.st!=='encantamento'||!SEQ_MK.includes(c.id)||['agendamento','negociacao'].includes(c.id))&&!(escondeColunaIA()&&c.id==='ia')&&!colunaOculta(c.id)).map(c=>{
    if(c.id==='resgate')return`<button class="col-btn" onclick="abrirModalResgate('${id}')" style="border-color:${c.cor};color:${c.cor}">${c.emoji} ${c.label}</button>`;
    const seqIdx=SEQ_MK.indexOf(c.id);
    const cor=seqIdx>-1?(seqIdx<=idxAtualMk?'var(--green)':'var(--red)'):c.cor;
    return`<button class="col-btn" onclick="moverLead('${id}','${c.id}')" style="border-color:${cor};color:${cor}">${c.emoji} ${c.label}</button>`;
  }).join('');
  const btnVend=lead.st!=='vendido'?`<button class="col-btn" onclick="abrirModalVendido('${id}')" style="border-color:var(--green);color:var(--green)">✅ Vendido</button>`:'';
  const btnPerd=lead.st!=='perdido'?`<button class="col-btn" onclick="abrirModalPerda('${id}')" style="border-color:var(--red);color:var(--red)">❌ Perdido</button>`:'';
  const btnRetomou=lead.st==='resgate'?`<button class="col-btn" onclick="moverLead('${id}','atendimento')" style="border-color:var(--green);color:var(--green)">✅ Retomou interesse</button>`:'';
  const btnOptOut=(lead.st==='perdido'&&!lead.optOutContato)?`<button class="col-btn" onclick="confirmarOptOut('${id}')" style="border-color:var(--tx3);color:var(--tx3)">🔕 Não quer mais contato</button>`:'';
  pnl.innerHTML=`
    <div class="detail-head">
      <span class="badge" style="background:${col.bg};color:${col.cor};font-size:12px">${col.emoji} ${col.label}</span>
      ${lead.st==='vendido'?`<span class="tag-conv"><i class="ti ti-check"></i> Vendido ${lead.dtVenda||''}</span>${isMaster()?`<input type="date" title="Corrigir data da venda (só Master)" value="${lead.dtVenda?brParaISO(lead.dtVenda):''}" onchange="editarDataVendaMk('${id}',this.value)" style="font-size:11px;padding:3px 5px;border:1px solid var(--bdr);border-radius:6px;font-family:var(--f)">`:''}`:''}
      ${lead.vendaRecuperada?`<span class="tag-conv" style="background:var(--purplel);color:var(--purple)"><i class="ti ti-refresh"></i> Venda recuperada</span>`:''}
      ${lead.optOutContato?`<span class="tag-conv" style="background:var(--bg3);color:var(--tx3)"><i class="ti ti-bell-off"></i> Não contatar (LGPD)</span>`:''}
      <button class="mod-close" onclick="fecharDetail()"><i class="ti ti-x"></i></button>
    </div>
    <div class="detail-body">
      <h3 style="font-size:18px;font-weight:700;margin-bottom:12px">${lead.clienteNome||'—'}</h3>
      <div class="d-section"><div class="d-section-title">Cliente</div>
        <div class="d-grid">
          <div class="d-field"><span class="lbl">Telefone</span><span class="val">${lead.clienteTel||'—'}${lead.clienteTel?` <button class="card-btn" style="display:inline-flex;margin-left:6px" onclick="abrirWhatsappLead('${lead.id}')" title="Chamar no WhatsApp"><i class="ti ti-brand-whatsapp"></i></button>`:''}</span></div>
          <div class="d-field"><span class="lbl">E-mail</span><span class="val${!lead.clienteEmail?' empty':''}">${lead.clienteEmail||'—'}</span></div>
        </div>
      </div>
      <div class="d-section"><div class="d-section-title">Lead</div>
        <div class="d-grid">
          <div class="d-field"><span class="lbl">ID</span><span class="val">${lead.id}</span></div>
          <div class="d-field"><span class="lbl">Data</span><span class="val">${lead.dt||'—'}</span></div>
          <div class="d-field"><span class="lbl">Origem</span><span class="val">${lead.origem||'—'}</span></div>
          <div class="d-field"><span class="lbl">Vendedor</span><span class="val">${lead.captador||lead.by||'—'}${lead.captadorReplicado?` <span style="color:var(--purple)">+ ${lead.captadorReplicado} (réplica)</span>`:''}</span></div>
          <div class="d-field"><span class="lbl">Tempo total (desde a criação)</span><span class="val">${lead._criadoEm?`<span class="live-timer" data-start="${lead._criadoEm}" style="color:var(--red);font-weight:700">calculando...</span>`:'—'}</span></div>
          ${timerEtapaHtml?`<div class="d-field"><span class="lbl">Tempo na etapa atual (${col.label})</span><span class="val">${timerEtapaHtml}</span></div>`:''}
          <div class="d-field" style="grid-column:1/-1"><span class="lbl">Veículo</span><span class="val">${lead.veiculo||'—'}</span></div>
          ${lead.veiculoTroca?`<div class="d-field" style="grid-column:1/-1"><span class="lbl">🔄 Veículo de troca</span><span class="val">${[lead.veiculoTroca.marca,lead.veiculoTroca.modelo,lead.veiculoTroca.ano,lead.veiculoTroca.cor].filter(Boolean).join(' ')||'—'}${lead.veiculoTroca.placa?` · ${lead.veiculoTroca.placa}`:''}</span></div>`:''}
          ${lead.valorFechado?`<div class="d-field" style="grid-column:1/-1"><span class="lbl">💰 Valor fechado (Termo de Venda)</span><span class="val" style="color:var(--green);font-weight:700">R$ ${Number(lead.valorFechado).toLocaleString('pt-BR')}${lead.formaPagamento?` · ${lead.formaPagamento}`:''}</span></div>`:''}
          ${lead.motivoPerda?`<div class="d-field" style="grid-column:1/-1"><span class="lbl">Motivo perda</span><span class="val" style="color:var(--red)">${lead.motivoPerda}</span></div>`:''}
          ${lead.resgateMotivo?`<div class="d-field" style="grid-column:1/-1"><span class="lbl">Estratégia de resgate</span><span class="val" style="color:var(--purple)">${lead.resgateMotivo}${lead.resgateData?` · Contato previsto: ${isoParaBR(lead.resgateData)}`:''}</span></div>`:''}
        </div>
        ${lead.obs?`<div style="background:var(--bg3);border-radius:var(--r);padding:10px 12px;font-size:12px;color:var(--tx2);line-height:1.6;margin-top:8px;white-space:pre-wrap">${lead.obs}</div>`:''}
      </div>
      <div class="d-section"><div class="d-section-title">Dashboard</div>
        <div class="col-select">${movBtns}${btnVend}${btnPerd}${btnRetomou}${btnOptOut}</div>
      </div>
      <div class="d-section"><div class="d-section-title">Histórico (${hist.length})</div>${histHtml}</div>
    </div>
    <div class="detail-foot">
      <button class="btn btn-outline btn-sm" onclick="abrirModalLead('${id}')"><i class="ti ti-pencil"></i> Editar</button>
      <button class="btn btn-red btn-sm" onclick="abrirModalObs('${id}')"><i class="ti ti-message-circle"></i> Registrar</button>
      <button class="btn btn-outline btn-sm" style="color:var(--red);border-color:var(--red)" onclick="confirmarExclusaoLead('${id}')"><i class="ti ti-trash"></i> Excluir</button>
    </div>`;
}
function confirmarExclusaoLead(id){
  const lead=G.mk.leads.find(l=>l.id===id);if(!lead)return;
  G.mk._excluindoId=id;
  document.getElementById('excluir-lead-nome').textContent=`${lead.id} — ${lead.clienteNome||'(sem nome)'}`;
  document.getElementById('ov-excluir-lead').classList.remove('hidden');
  setTimeout(()=>document.getElementById('btn-excluir-nao').focus(),50);
}
async function executarExclusaoLead(){
  const id=G.mk._excluindoId;if(!id)return;
  try{
    if(!G.mk.modoDemo)await db.collection('leads').doc(id).delete();
    G.mk.leads=G.mk.leads.filter(l=>l.id!==id);
    fecharModal('ov-excluir-lead');
    fecharDetail();
    toast('Lead excluído');
    renderMarketing();
  }catch(e){console.error(e);toast('Erro ao excluir','red');}
}


